import{_ as e,c as o,o as a,a1 as t,a2 as c,a3 as l}from"./chunks/framework.7AAjiCkA.js";const I=JSON.parse('{"title":"AI即时翻译服务","description":"","frontmatter":{},"headers":[],"relativePath":"AI实验室/AI即时翻译服务.md","filePath":"AI实验室/AI即时翻译服务.md"}'),i={name:"AI实验室/AI即时翻译服务.md"},d=t('<h1 id="ai即时翻译服务" tabindex="-1">AI即时翻译服务 <a class="header-anchor" href="#ai即时翻译服务" aria-label="Permalink to &quot;AI即时翻译服务&quot;">​</a></h1><h3 id="下一代翻译-何止是翻译" tabindex="-1">下一代翻译，何止是翻译 <a class="header-anchor" href="#下一代翻译-何止是翻译" aria-label="Permalink to &quot;下一代翻译，何止是翻译&quot;">​</a></h3><p><img src="'+c+'" alt="翻译服务"></p><p>随着人工智能技术的不断发展，AI对于语言领域的识别同样是发展迅猛。</p><p><code>沉浸式翻译</code>（该工具软件来自于网络，非本站提供）结合 <code>BASETEC</code> 的人工智能翻译接口，能让你以母语者水平轻易阅读外文资料。</p><h3 id="特色" tabindex="-1">特色 <a class="header-anchor" href="#特色" aria-label="Permalink to &quot;特色&quot;">​</a></h3><ol><li>极快的翻译速度</li><li>沉浸式的仿原生UI布局，提供语言比对</li><li>支持全球所有语言之间的互译</li><li>支持鼠标“指哪译哪”及全篇替换语言</li><li>支持本地文档翻译</li></ol><h3 id="使用方式" tabindex="-1">使用方式 <a class="header-anchor" href="#使用方式" aria-label="Permalink to &quot;使用方式&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">说明</p><p>BASETEC为所有注册用户提供免费的接口。</p></div><ol><li><p>搜索沉浸式翻译官网，或点击此链接前往沉浸式翻译官网：<a href="https://immersivetranslate.com" target="_blank" rel="noreferrer">https://immersivetranslate.com</a>，按照说明安装浏览器插件；</p></li><li><p>从 <code>BASETEC</code> 获取 <code>沉浸式翻译API接口</code> 。</p></li></ol><p>具体方法：前往<a href="https://basetec.top" target="_blank" rel="noreferrer">BASETEC官网</a>，注册账户（与X-Chat用户信息互通，如已注册可直接登录），点击导航栏的 <code>项目</code> / <code>工单支持</code> ，找到 <code>沉浸式翻译接口API接口权限申请</code> ，按提示获取。</p><ol start="3"><li>进入沉浸式翻译设置，如下图；</li></ol><p><img src="'+l+'" alt="翻译服务"></p><ul><li><p>在左侧列表中选择 <code>基本设置</code> ，在右侧的 <code>翻译服务</code> 下拉列表中选择 <code>OpenAI</code> ；</p></li><li><p>在 <code>APIKEY</code> 输入获取的翻译服务专属令牌，同时勾选 <code>输入自定义模型名称</code> ， 输入获取的专属模型；</p></li></ul><div class="warning custom-block"><p class="custom-block-title">注意</p><p>只有从BASETEC申请的指定令牌和模型才可用于翻译服务，普通令牌接入后将触发账户封禁！</p></div><ul><li><p>继续下划，点击 <code>展开更多自定义选项</code> ,在 <code>自定义API接口地址</code> 中输入获取的接口地址，最后划到顶部，点击 <code>点击测试服务</code>。如显示 <code>验证成功</code> ，即可关闭正常使用。</p></li><li><p>如有必要，可点击左侧的 <code>悬浮球</code> 以打开浏览器悬浮快捷操作。</p></li></ul>',16),r=[d];function s(p,n,_,h,m,A){return a(),o("div",null,r)}const f=e(i,[["render",s]]);export{I as __pageData,f as default};
